package com.pet.buscaativa;

import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.*;
import org.springframework.beans.factory.annotation.Autowired;
import com.pet.buscaativa.entities.*;
import com.pet.buscaativa.entities.dto.*;
import com.pet.buscaativa.entities.enums.*;
import com.pet.buscaativa.config.AgendaHorarioProperties;

class CancelRecoveryIntegrationTests extends CancellationRegularizationSupport {
    @Autowired AgendaHorarioProperties grid;
    @ParameterizedTest @CsvSource({"owner,200","admin,200","colleague,403","reception,403","foreign,404"})
    void rr01And11To15RecoveryIsPerAppointmentAndUnit(String role,int expected) throws Exception {var a=canceled(true);var actor=actor(role);var before=database();long rows=appointments.count(),events=history.count(),audits=regularizations.count();var r=recover(actor,a,recovery(a));assertEquals(expected,businessStatus(r),r.getContentAsString());if(expected!=200){assertEquals(before,database());return;}var saved=appointment(a.getId());assertEquals(SituacaoReserva.AGENDADA,saved.getSituacaoReserva());assertEquals(FrequenciaAssistencial.NAO_REGISTRADA,saved.getFrequenciaAssistencial());assertTrue(saved.getOcupaVaga());assertEquals(a.getVersion()+1,saved.getVersion());assertEquals(a.getDataAgendamento(),saved.getDataAgendamento());assertEquals(a.getHoraAtendimento(),saved.getHoraAtendimento());assertEquals(rows,appointments.count());assertEquals(events,history.count());assertEquals(audits+1,regularizations.count());var row=jdbc.queryForMap("select * from tb_auditoria_regularizacao_cancelamento where agendamento_id=?",a.getId());assertEquals("RECUPERACAO_RESERVA",row.get("TIPO_REGULARIZACAO"));assertEquals("CANCELADA",row.get("RESERVA_ANTERIOR"));assertEquals("AGENDADA",row.get("RESERVA_RESULTANTE"));assertEquals("NAO_REGISTRADA",row.get("FREQUENCIA_RESULTANTE"));assertEquals(actor.getId(),row.get("ATOR_ID"));assertEquals(professional.getId(),row.get("RESPONSAVEL_ID"));}
    @ParameterizedTest @ValueSource(strings={"zero","full","blocked","grid","professional","patient","no_offer"})
    void rr02To07UnavailableOfferOrCollisionNeverPartiallyRecovers(String defect) throws Exception {var a=canceled(true);int previous=grid.getIntervaloMinutos();try{tx(()->{switch(defect){case "zero"->capacity(professional,DAY,TurnoEnum.TARDE,0);case "full"->{capacity(professional,DAY,TurnoEnum.TARDE,1);var busy=seed(other,professional,SituacaoAtendimento.AGENDADO,DAY,"16:00");busy.setTurnoAgendamento(TurnoEnum.TARDE);appointments.saveAndFlush(busy);}case "blocked"->{var b=new BloqueioAgenda();b.setUsuario(professional);b.setDataInicio(DAY);b.setDataFim(DAY);b.setMotivoBloqueio("Bloqueio sintético ativo.");blocks.saveAndFlush(b);}case "grid"->grid.setIntervaloMinutos(45);case "professional"->seed(other,professional,SituacaoAtendimento.AGENDADO,DAY,"15:00");case "patient"->seed(patient,colleague,SituacaoAtendimento.AGENDADO,DAY,"15:00");case "no_offer"->{var config=exceptions.findByUsuarioAndDataAndTurno(professional,DAY,TurnoEnum.TARDE).orElseThrow();exceptions.delete(config);exceptions.flush();}default->throw new IllegalArgumentException();}return null;});var before=database();int expected=defect.equals("grid")?422:409;assertEquals(expected,recover(a));assertEquals(before,database());}finally{grid.setIntervaloMinutos(previous);}}
    @ParameterizedTest @CsvSource({"14:59,200","15:00,409","15:01,409"})
    void rr10RecoveryIsStrictlyBeforeSlot(String time,int expected) throws Exception {var a=canceled(true);now(DAY.atTime(LocalTime.parse(time)));var before=database();assertEquals(expected,recover(a));if(expected!=200)assertEquals(before,database());}
    @Test void rr08RealP05SuccessorRestoresRemarcadaWithoutTouchingOriginal() throws Exception {var a=legitimateRescheduledCancellation();var original=tx(()->appointment(a.getId()).getAgendamentoOriginal().getId());var source=jdbc.queryForMap("select * from tb_agendamento where id=?",original);assertEquals(200,recover(a));assertEquals(SituacaoReserva.REMARCADA,appointment(a.getId()).getSituacaoReserva());assertEquals(original,tx(()->appointment(a.getId()).getAgendamentoOriginal().getId()));assertTrue(appointment(a.getId()).isRemarcacaoAposFalta());assertEquals(source,jdbc.queryForMap("select * from tb_agendamento where id=?",original));}
    @ParameterizedTest @EnumSource(value=SituacaoAtendimento.class,names={"AGENDADO","REMARCADO","REMARCADO_ORIGEM","PRESENTE","FALTOU"})
    void rr09WrongSourceStateIsNotRecovered(SituacaoAtendimento state) throws Exception {var a=tx(()->seed(patient,professional,state,DAY,"15:00"));var before=database();assertEquals(409,recover(a));assertEquals(before,database());}
    @Test void rr17And18StaleAndRepeatedRecoveryNeverCreatesPhantomAudit() throws Exception {var a=canceled(true);var before=database();assertEquals(409,recover(admin,a,new RecuperarReservaCanceladaDTO(a.getVersion()+1,REASON)).getStatus());assertEquals(before,database());assertEquals(200,recover(a));before=database();assertEquals(409,recover(a));assertEquals(before,database());assertEquals(409,recover(appointment(a.getId())));assertEquals(before,database());}
    @Test void clientCannotChooseOwnerActorScheduleOrRecoveredState() throws Exception {var a=canceled(true);var body=new HashMap<String,Object>();body.put("version",a.getVersion());body.put("justificativa",REASON);body.put("atorId",colleague.getIdPublico());body.put("usuarioId",colleague.getIdPublico());body.put("situacaoReserva","REMARCADA");body.put("dataAgendamento",DAY.plusDays(10));body.put("horaAtendimento","07:00");assertEquals(200,recover(admin,a,body).getStatus());assertEquals(DAY,appointment(a.getId()).getDataAgendamento());assertEquals(LocalTime.of(15,0),appointment(a.getId()).getHoraAtendimento());assertEquals(SituacaoReserva.AGENDADA,appointment(a.getId()).getSituacaoReserva());assertEquals(admin.getId(),jdbc.queryForObject("select ator_id from tb_auditoria_regularizacao_cancelamento where agendamento_id=?",Long.class,a.getId()));}
}
